Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('98530608046031fae7028ace62701d5b41d411c71d0d266af228e066c1a38584',), event=Authored(todo='wasmsize', at=datetime(2026, 11, 21, 19, 55, 9, 229817), actor='bmabsout', kind='suzateryTodo', created=datetime(2026, 11, 4, 0, 0, 0), body="Every shipped wasm module stays within a brotli size budget the gate enforces and ratchets; the pages' views module is back near 1 MB raw.", spec=Flat(value=0.45), rationale=('A module that grows is more for a phone to download and compile after each deploy.',), category='', waiting_on='', detail="To measure before any cut, noted on 2026-11-21: the two modules the browser loads (the store's, about 5.0 MB, in a worker; the views', about 3.7 MB, on the page) each hold their own copy of the library's core and of the shared crates. One module file served to both threads would be downloaded and compiled once and instantiated twice: measure its size against the two, and what each thread then pays to start. The Typst module (22 MB) is not part of this: it is fetched only the first time a Typst view is drawn.\n\nA design question to answer before more cuts, noted on 2026-11-21: today the store's module runs in a worker and the views' module on the page, and the two speak JSON across threads. One module in the worker holding both the replica and the pages' runtime, with the page thread only painting the patches it is sent and sending inputs back, would read the store in place, decode nothing twice, compile nothing on the page's thread and ship one file. What it costs is the question: an input's round trip to the worker (typing in the composer, a scroll), and what must stay on the page. It waits for the trace of the first draw that streamfirstcompile is taking, and it is a note before it is code.", source=None, subtodos=(), notes=(), note=''))